    1: // 屏幕形态纯逻辑层。系统设备信息由适配器提供。
    2: 
    3: function finite(value) {
    4:   return typeof value === 'number' && Number.isFinite(value) && value > 0;
    5: }
    6: 
    7: function resolveLayout(info) {
    8:   const source = info || {};
    9:   const shape = source.screenShape === 'rect' ? 'square' : 'round';
   10:   const shortestSide = finite(source.screenWidth) && finite(source.screenHeight)
   11:     ? Math.min(source.screenWidth, source.screenHeight)
   12:     : 480;
   13:   const size = shortestSide < 400
   14:     ? 'compact'
   15:     : shortestSide >= 560
   16:       ? 'spacious'
   17:       : 'regular';
   18: 
   19:   return {
   20:     shape,
   21:     size,
   22:     className: `screen-${shape} size-${size}`,
   23:   };
   24: }
   25: 
   26: module.exports = { resolveLayout };
