    4: export function getScreenLayout() {
    5:   return new Promise((resolve) => {
    6:     const fallback = () => resolve(layout.resolveLayout(null));
    7:     try {
    8:       device.getInfo({
    9:         success: (info) => resolve(layout.resolveLayout(info)),
   10:         fail: fallback,
   11:       });
   12:     } catch (error) {
   13:       fallback();
   14:     }
   15:   });
   16: }
